  plan: [['5 min', 'Obruč a tanier: ktorý je kružnica a ktorý kruh?'], ['15 min', 'Vennov diagram a vzorce.'], ['15 min', 'Meranie: žiaci odmerajú obvod a priemer plechoviek a vydelia ich.'], ['10 min', 'Úlohy a kvíz.']],
