  scene: { svg: `<svg viewBox="0 0 1200 640" xmlns="http://www.w3.org/2000/svg"><rect width="1200" height="640" fill="#f5f5f5"/><g transform="translate(600 160)"><path d="M0 0V400" stroke="#6d4c41" stroke-width="16"/><path d="M-140 400h280" stroke="#6d4c41" stroke-width="20"/><circle r="16" fill="#ffb300"/><g><animateTransform attributeName="transform" type="rotate" values="-1.5;1.5;-1.5" dur="6s" repeatCount="indefinite"/><path d="M-380 0H380" stroke="#8d6e63" stroke-width="10"/><g stroke="#8d6e63" stroke-width="3"><path d="M-380 0l-80 140M-380 0l80 140M380 0l-80 140M380 0l80 140"/></g><path d="M-480 140h200q-100 40-200 0z" fill="#b0bec5"/><path d="M280 140h200q-100 40-200 0z" fill="#b0bec5"/><g fill="#42a5f5" stroke="#1565c0" stroke-width="4"><rect x="-470" y="80" width="56" height="56" rx="6"/><rect x="-408" y="80" width="56" height="56" rx="6"/><rect x="-346" y="80" width="56" height="56" rx="6"/></g><g fill="#ffca28" stroke="#f57f17" stroke-width="4"><path d="M-360 76l20-40h20l20 40z"/></g><g fill="#ffca28" stroke="#f57f17" stroke-width="4"><path d="M300 136l20-40h40l20 40z"/><path d="M390 136l20-40h40l20 40z"/><path d="M345 96l20-40h40l20 40z"/></g></g></g></svg>`,
   points: [{ t: 'Neznáma', d: 'Modré krabičky majú rovnakú hmotnosť x, ktorú hľadáme.', e: 'Krabička je neznáma x.', ic: 'star', x: 15, y: 47 }, { t: 'Ľavá strana', d: 'Tri krabičky a závažie 5 kg: 3x + 5.', e: 'Vľavo je 3x + 5.', ic: 'book', x: 22, y: 30 }, { t: 'Pravá strana', d: 'Závažia spolu 20 kg.', e: 'Vpravo je 20.', ic: 'map', x: 82, y: 30 }, { t: 'Rovnováha', d: 'Váhy sú v rovnováhe, preto 3x + 5 = 20. Čo urobíme na jednej strane, urobíme aj na druhej.', e: 'Obe strany sú rovnako ťažké.', ic: 'cross', x: 50, y: 15 }, { t: 'Riešenie', d: 'Odoberieme 5 kg z oboch strán a rozdelíme na tri: x = 5 kg.', e: 'Jedna krabička váži 5 kg.', ic: 'sun', x: 50, y: 88, l: 2 }] },
  cards: [{ q: 'Čo znamená vyriešiť rovnicu?', a: 'Nájsť číslo, ktoré po dosadení dá pravdivú rovnosť.' }, { q: 'Vyrieš: x + 7 = 12.', a: 'x = 5.' }, { q: 'Vyrieš: 4x = 28.', a: 'x = 7.' }, { q: 'Čo je skúška?', a: 'Dosadenie výsledku do pôvodnej rovnice.' }, { q: 'Vyrieš: 2x − 4 = 10.', a: 'x = 7.', l: 2 }, { q: 'Vyrieš: 5x + 3 = 2x + 18.', a: 'x = 5.', l: 3 }],
